/* Caliper UI: semantic roles, shared by copied components and the playground.
   Theme and density also resolve on any element with data-theme / data-density,
   so a preview region can switch independently of the page.
   Values follow docs/DESIGN-SYSTEM.md: flat fills carry depth, the primary action is ink,
   one accent (default Sky) marks selection and data, three shadows. Names are unchanged
   so installed parts keep working; the retired material tokens now resolve to flat values. */
:root,
[data-theme="light"] {
  color-scheme: light;
  /* Series: the accent leads, then violet, amber, teal and rose at one OKLCH lightness and chroma, so no series shouts
     and every mark stands about 3:1 off the grounds; a neutral grey closes the set for "Other". */
  --chart-1: var(--chart-accent);
  --chart-2: oklch(0.56 0.19 295);
  --chart-3: oklch(0.64 0.17 55);
  --chart-4: oklch(0.6 0.13 170);
  --chart-5: oklch(0.6 0.2 355);
  --chart-6: oklch(0.62 0 0);
  /* Neutrals: page, stage, tile, field. */
  --background: #f4f4f5;
  --foreground: #0a0a0b;
  --surface: #ffffff;
  --elevated: #ffffff;
  --elevated-glass: rgb(255 255 255 / 97%);
  --edge-light: rgb(255 255 255 / 80%);
  --edge-glow: rgb(20 20 28 / 8%);
  --blur-overlay: 20px;
  --muted: #e9e9ec;
  --muted-foreground: #5f5f68;
  /* The second tone of a two-tone headline, placeholders and keycaps, and the lifted part of a control (segment, thumb). */
  --foreground-2: #8e8e96;
  --faint: #6c6c75;
  --knob: #ffffff;
  --border: rgb(0 0 0 / 8%);
  --border-strong: #8a8a94;
  /* The customer's accent: neutral by default (ink here, near-white in the dark block), so the library is monochrome until
     a hue is picked. Change the seven --accent* values and --chart-accent here and in the dark block together (the docs'
     Customize panel copies a ready block). Light: --accent is a deep fill with white text at 4.5:1. Dark: --accent is a
     lighter tone of the hue with dark text at 4.5:1. --accent-text reads at 4.6:1 as text on every ground. --chart-accent
     leads the chart series (a calm blue while the accent is neutral, so data still reads as data). */
  --accent: #18181b;
  --accent-foreground: #ffffff;
  --accent-hover: #2a2a2e;
  --accent-press: #000000;
  --accent-text: #27272a;
  --accent-soft: rgb(24 24 27 / 8%);
  --chart-accent: #2f6fdb;
  /* The accent's deep tone (its white-text fill) in both themes, for surfaces that always carry white: avatar orbs. */
  --accent-deep: #4b4b52;
  /* The primary action is ink. */
  --primary: #0a0a0b;
  --primary-foreground: #ffffff;
  --primary-hover: #2a2a2e;
  --primary-press: #000000;
  /* Status tints are opaque on purpose: contrast tools and nested surfaces read one colour, not an alpha. */
  /* Brand marks (today, now, active, drag) follow the accent; in light they use its readable tone. */
  --brand: var(--accent-text);
  --brand-foreground: #ffffff;
  --brand-subtle: var(--accent-soft);
  --river: #5d4fb9;
  --river-subtle: #eeeeff;
  --ring: var(--accent-text);
  --success: #0e793c;
  --success-subtle: #dff7e9;
  --warning: #8a5a00;
  --warning-subtle: #fdf1dc;
  --destructive: #cf0f52;
  --destructive-foreground: #ffffff;
  --destructive-subtle: #fee3ec;
  --danger: #cf0f52;
  --danger-foreground: #ffffff;
  --overlay: rgb(12 12 18 / 30%);
  --shadow-overlay: 0 12px 40px rgb(20 20 28 / 14%);
  --shadow-feedback: 0 4px 12px rgb(20 20 28 / 8%);
  --shadow-control: none;
  --radius-control: 12px;
  --radius-surface: 16px;
  --radius-overlay: 20px;
  --duration-instant: 0ms;
  --duration-fast: 120ms;
  --duration-normal: 180ms;
  --duration-deliberate: 280ms;
  --duration-travel: 400ms;
  --duration-showcase: 600ms;
  --delay-stagger: 60ms;
  --duration-loading: 1000ms;
  --duration-skeleton: 1600ms;
  --duration-marquee: 24000ms;
  --motion-enter-distance: 4px;
  --motion-showcase-distance: 16px;
  --motion-press-scale: 0.97;
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-settle: cubic-bezier(0.22, 1.2, 0.36, 1);
  --ease-in: cubic-bezier(0.4, 0, 1, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-showcase: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-linear: linear;
  --control-height: 40px;
  --nav-height: 40px;
  --row-padding: 16px;
  /* Fills replace materials: a control is a flat fill one step above its ground. */
  --raised: #e9e9ec;
  --raised-hover: #dfdfe3;
  --raised-press: #d6d6db;
  --sunken: #e9e9ec;
  /* A selected row or item: the customer's accent mixed into the ground, stronger than the hover fill in both themes. */
  --selected: color-mix(in srgb, var(--accent) 22%, var(--background));
  --danger-fill: #f31260;
  --danger-fill-hover: #e00f58;
  --danger-fill-press: #c70c4d;
  --danger-fill-foreground: #ffffff;
  /* Retired materials, kept as names so installed parts resolve: no lift, no inner shade. */
  --shadow-raised: none;
  --shadow-raised-press: none;
  --shadow-accent: none;
  --shadow-accent-press: none;
  --shadow-danger: none;
  --shadow-danger-press: none;
  --shadow-plate: 0 1px 3px rgb(0 0 0 / 20%);
  --shadow-sunken: none;
  /* Fields keep a 3:1 boundary (WCAG 1.4.11); focus is a 2px ring. */
  --field: #ffffff;
  --shadow-field: inset 0 0 0 1px var(--border-strong);
  --shadow-field-hover: inset 0 0 0 1px color-mix(in srgb, var(--border-strong) 60%, var(--foreground));
  --ring-halo: transparent;
  --shadow-field-focus: 0 0 0 2px var(--ring);
  --shadow-field-invalid: 0 0 0 2px var(--danger-fill);
  --shadow-field-quiet: inset 0 0 0 1px var(--border);
  --radius-mark: 8px;
  --radius-button: 12px;
  --radius-touch: 16px;
  --motion-press-travel: 1px;
}

:root[data-theme="dark"],
[data-theme="dark"] {
  color-scheme: dark;
  /* Series: the same hues a step lighter for the dark grounds. */
  --chart-1: var(--chart-accent);
  --chart-2: oklch(0.7 0.16 295);
  --chart-3: oklch(0.75 0.15 60);
  --chart-4: oklch(0.72 0.12 170);
  --chart-5: oklch(0.72 0.16 355);
  --chart-6: oklch(0.6 0 0);
  /* A soft near-black in pure grey (no tint): page, stage, tile, field, each a step lighter. */
  --background: #161616;
  --foreground: #f5f5f5;
  --surface: #1b1b1b;
  --elevated: #212121;
  --elevated-glass: rgb(33 33 33 / 97%);
  --edge-light: rgb(255 255 255 / 16%);
  --edge-glow: rgb(255 255 255 / 8%);
  --muted: #2a2a2a;
  --muted-foreground: #a3a3a3;
  --foreground-2: #737373;
  --faint: #8a8a8a;
  --knob: #444444;
  --border: rgb(255 255 255 / 8%);
  --border-strong: #7a7a7a;
  --accent: #ececec;
  --accent-foreground: #161616;
  --accent-hover: #ffffff;
  --accent-press: #d4d4d4;
  --accent-text: #e4e4e4;
  --accent-soft: rgb(236 236 236 / 12%);
  --chart-accent: #7aa5f5;
  --accent-deep: #4b4b52;
  --primary: #fafafa;
  --primary-foreground: #0a0a0b;
  --primary-hover: #e4e4e7;
  --primary-press: #d4d4d8;
  --brand: var(--accent);
  --brand-foreground: var(--accent-foreground);
  --river: #c4c4ff;
  --river-subtle: #323245;
  --success: #17c964;
  --success-subtle: #153524;
  --warning: #f5a524;
  --warning-subtle: #3d2e19;
  --destructive: #ff5c8a;
  --destructive-foreground: #161616;
  --destructive-subtle: #3c1423;
  --danger: #ff5c8a;
  --danger-foreground: #161616;
  --overlay: rgb(0 0 0 / 55%);
  --shadow-overlay: 0 12px 40px rgb(0 0 0 / 40%);
  --shadow-feedback: 0 4px 12px rgb(0 0 0 / 24%);
  --raised: #2a2a2a;
  --raised-hover: #333333;
  --raised-press: #1f1f1f;
  --sunken: #1b1b1b;
  --shadow-plate: 0 1px 3px rgb(0 0 0 / 40%);
  --field: #2a2a2a;
  /* Derived tokens are restated so a dark region inside a light page resolves them against its own values. */
  --brand-subtle: var(--accent-soft);
  --ring: var(--accent-text);
  --selected: color-mix(in srgb, var(--accent) 24%, var(--background));
  --shadow-field: inset 0 0 0 1px var(--border-strong);
  --shadow-field-hover: inset 0 0 0 1px color-mix(in srgb, var(--border-strong) 60%, var(--foreground));
  --shadow-field-focus: 0 0 0 2px var(--ring);
  --shadow-field-quiet: inset 0 0 0 1px var(--border);
}

:root[data-density="compact"],
[data-density="compact"] {
  --control-height: 36px;
  --nav-height: 36px;
  --row-padding: 12px;
}

/* Touch targets stay generous even when a desktop prefers compact density. */
@media (pointer: coarse), (max-width: 767px) {
  :root,
  :root[data-density="compact"],
  [data-density="compact"] {
    --control-height: 44px;
    --nav-height: 44px;
    --radius-button: var(--radius-touch);
  }
}

@media (prefers-reduced-motion: reduce) {
  :root,
  [data-theme] {
    --duration-fast: var(--duration-instant);
    --duration-normal: var(--duration-instant);
    --duration-deliberate: var(--duration-instant);
    --duration-travel: var(--duration-instant);
    --duration-showcase: var(--duration-instant);
    --delay-stagger: var(--duration-instant);
    --duration-loading: var(--duration-instant);
    --duration-skeleton: var(--duration-instant);
    --motion-enter-distance: 0px;
    --motion-showcase-distance: 0px;
    --motion-press-scale: 1;
    --motion-press-travel: 0px;
  }
}

/* Import after Tailwind and Caliper UI tokens. Values stay in tokens.css. */
@custom-variant dark (&:where([data-theme="dark"], [data-theme="dark"] *));

@theme inline {
  --default-transition-duration: var(--duration-fast);
  --default-transition-timing-function: var(--ease-out);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-surface: var(--surface);
  --color-elevated: var(--elevated);
  --color-muted: var(--muted);
  --color-selected: var(--selected);
  --color-raised: var(--raised);
  --color-raised-hover: var(--raised-hover);
  --color-sunken: var(--sunken);
  --color-field: var(--field);
  --color-accent-hover: var(--accent-hover);
  --color-danger-fill: var(--danger-fill);
  --color-danger-fill-foreground: var(--danger-fill-foreground);
  --color-muted-foreground: var(--muted-foreground);
  --color-border: var(--border);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent-text: var(--accent-text);
  --color-accent-soft: var(--accent-soft);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-ring: var(--ring);
  --color-border-strong: var(--border-strong);
  --color-brand: var(--brand);
  --color-brand-foreground: var(--brand-foreground);
  --color-brand-subtle: var(--brand-subtle);
  --color-river: var(--river);
  --color-river-subtle: var(--river-subtle);
  --color-success: var(--success);
  --color-success-subtle: var(--success-subtle);
  --color-warning: var(--warning);
  --color-warning-subtle: var(--warning-subtle);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-destructive-subtle: var(--destructive-subtle);
  --color-danger: var(--danger);
  --color-danger-foreground: var(--danger-foreground);
  --radius-control: var(--radius-control);
  --radius-surface: var(--radius-surface);
  --radius-overlay: var(--radius-overlay);
  --radius-mark: var(--radius-mark);
  --radius-button: var(--radius-button);
  --radius-touch: var(--radius-touch);
  --shadow-overlay: var(--shadow-overlay);
  --shadow-feedback: var(--shadow-feedback);
  --shadow-raised: var(--shadow-raised);
  --shadow-plate: var(--shadow-plate);
  --shadow-sunken: var(--shadow-sunken);
  --shadow-field: var(--shadow-field);
}

/* Caliper UI base styles: the few rules no single part owns, and shared animations. Import once, after the tokens. */
@layer theme, base, components, utilities;

@layer components {
  /* A size container ignores its content when sizing, so in a centring flex
     or grid parent it would collapse to nothing. It fills its slot instead;
     width and max-width utilities still win. */
  .\@container,
  [class*="@container/"] {
    inline-size: 100%;
    min-inline-size: 0;
  }

  /* A grid without declared columns would get an auto track that grows to its
     widest unbreakable row (a chip row, a badge, a nowrap title) and push past
     a phone screen. Its single track can shrink instead; grid-cols utilities
     and component rules later in this file still set real columns. */
  .grid { grid-template-columns: minmax(0, 1fr); }

  .lucide {
    stroke-width: 1.75;
  }
}

html[data-theme-reveal]::view-transition-old(root),
  html[data-theme-reveal]::view-transition-new(root) {
  mix-blend-mode: normal;
  animation: none;
}

html[data-theme-reveal="circle"]::view-transition-new(root) {
  animation: caliper-theme-circle var(--duration-showcase) var(--ease-showcase) both;
}

html[data-theme-reveal="seam"]::view-transition-new(root) {
  animation: caliper-theme-seam var(--duration-showcase) var(--ease-showcase) both;
}

html[data-theme-reveal="wipe"]::view-transition-new(root) {
  animation: caliper-theme-wipe var(--duration-showcase) var(--ease-showcase) both;
}
@layer components {
  [data-variant="lines"] { display: grid; width: 100%; max-width: 20rem; }
  [data-slot="page-frame"] { border: 1px solid var(--border); border-radius: 1rem; background: var(--background); padding: 1.5rem; overflow: hidden; min-width: 0; }
  [data-slot="template-frame"] { border: 1px solid var(--border); border-radius: 1rem; background: var(--background); overflow: hidden; min-width: 0; }
  [data-slot="template-bar"] { display: flex; align-items: center; gap: 0.5rem; padding: 0.5rem 0.75rem; border-bottom: 1px solid var(--border); background: var(--surface); font-size: 0.75rem; color: var(--muted-foreground); }
  [data-slot="template-bar"] i { width: 0.55rem; height: 0.55rem; border-radius: 999px; background: var(--border); }
  [data-slot="template-body"] { max-height: 34rem; overflow: auto; }

  /* ── Backdrops ────────────────────────────────────── */
  [data-slot="block-grid-lines"] {
    position: absolute; inset: 0; z-index: 0; pointer-events: none;
    background-image:
      linear-gradient(var(--k-line) 1px, transparent 1px),
      linear-gradient(90deg, var(--k-line) 1px, transparent 1px);
    background-size: 48px 48px;
    background-position: center top;
    mask-image: radial-gradient(ellipse 80% 70% at 50% 0%, #000 30%, transparent 100%);
  }

  [data-chart-measuring], [data-chart-measuring] * { transition: none !important; }
  li[data-state="next"] { color: var(--muted-foreground); }

  /* Depth set start (2026-10-16) */
  /* Depth set (2026-10-16). Perspective belongs to a part's own stage, never to the page or an app shell. */
  [data-depth-set] {
    --depth-near: 800px;
    --depth-mid: 1000px;
    --depth-far: 1400px;
    --depth-step: 24px;
    --depth-tilt-max: 8deg;
    position: relative;
    min-width: 0;
    container-type: inline-size;
  }
  /* A bare text box with no focus style of its own (a hand-built input with a border) gets one ring drawn over its edge.
     Zero specificity, so any component rule or outline-none utility wins. */
  :where(input:not([type="checkbox"], [type="radio"], [type="range"], [type="color"], [type="file"], [type="button"], [type="submit"], [type="reset"], [type="image"]), textarea):where(:focus-visible) {
    outline: 2px solid var(--ring);
    outline-offset: -1px;
  }
  @keyframes caliper-select-in {
    from {
      opacity: 0;
      transform: scaleY(0.96);
    }
  }
}

@keyframes caliper-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes caliper-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes caliper-dialog-enter {
  from {
    opacity: 0;
    transform: translateY(var(--motion-enter-distance))
      scale(var(--motion-press-scale));
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes caliper-feedback-enter {
  from {
    opacity: 0;
    transform: translateY(var(--motion-enter-distance));
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes caliper-feedback-symbol-enter {
  from {
    opacity: 0;
    scale: var(--motion-press-scale);
  }
  to {
    opacity: 1;
    scale: 1;
  }
}

@keyframes caliper-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes caliper-skeleton-pulse {
  0%,
  100% {
    opacity: 0.45;
  }
  50% {
    opacity: 1;
  }
}

@keyframes caliper-digit-in {
  from {
    transform: translateY(-70%);
  }
  to {
    transform: translateY(0);
  }
}

@keyframes caliper-calendar-next {
  from {
    opacity: 0;
    transform: translateX(16px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes caliper-calendar-prev {
  from {
    opacity: 0;
    transform: translateX(-16px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes caliper-day-select {
  from {
    transform: scale(0.86);
  }
  to {
    transform: none;
  }
}

@keyframes caliper-reject {
  0%,
  100% {
    transform: none;
  }
  35% {
    transform: translateX(-4px);
  }
  70% {
    transform: translateX(4px);
  }
}

@keyframes caliper-menu-enter {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes caliper-theme-circle {
  from {
    clip-path: circle(0 at var(--theme-origin-x) var(--theme-origin-y));
  }
  to {
    clip-path: circle(var(--theme-radius) at var(--theme-origin-x) var(--theme-origin-y));
  }
}

@keyframes caliper-theme-seam {
  from {
    clip-path: inset(0 50% 0 50%);
  }
  to {
    clip-path: inset(0 0 0 0);
  }
}

@keyframes caliper-theme-wipe {
  from {
    clip-path: inset(100% 0 0 0);
  }
  to {
    clip-path: inset(0 0 0 0);
  }
}

@layer components {
  @keyframes caliper-tab-swap {
    from {
      opacity: 0;
      transform: translateX(
        calc(var(--tab-direction, 1) * var(--motion-enter-distance))
      );
    }
    to {
      opacity: 1;
      transform: translateX(0);
    }
  }
  @keyframes caliper-chart-draw {
    from {
      stroke-dasharray: 1;
      stroke-dashoffset: 1;
    }
    to {
      stroke-dasharray: 1;
      stroke-dashoffset: 0;
    }
  }
  @keyframes caliper-ring-fill {
    from {
      stroke-dasharray: 0 100;
    }
  }
  @keyframes caliper-heat-in {
    from {
      opacity: 0;
    }
  }
  @keyframes caliper-status-in {
    from {
      opacity: 0;
      transform: scaleY(0.4);
    }
  }
  @keyframes caliper-calendar-next {
    from {
      opacity: 0;
      translate: 14px 0;
    }
  }
  @keyframes caliper-calendar-prev {
    from {
      opacity: 0;
      translate: -14px 0;
    }
  }
  @keyframes caliper-skeleton-pulse {
    50% {
      opacity: 0.45;
    }
  }
  @keyframes caliper-chip-in {
    from {
      opacity: 0;
      scale: 0.92;
    }
  }
  @keyframes caliper-thread-in {
    from {
      opacity: 0;
      translate: 0 6px;
    }
  }
  @keyframes caliper-pulse-soft {
    50% {
      opacity: 0.5;
    }
  }
  @keyframes caliper-scrim-in {
    to {
      opacity: 1;
    }
  }
  @keyframes rec-pulse { 50% { opacity: 0.25; } }
  @keyframes vt-pulse { 50% { opacity: 0.45; } }
  @keyframes think-in { from { opacity: 0; transform: translateY(4px); } }
  @keyframes caliper-faq-open { from { opacity: 0; translate: 0 -6px; } }
  @media (prefers-reduced-motion: no-preference) {
    @keyframes caliper-select-in { from { background-color: transparent; } }
  }
  @keyframes caliper-unsaved-in { from { opacity: 0; transform: translateY(12px); } }
  @media (prefers-reduced-motion: no-preference) {
    @keyframes caliper-app-swap { from { opacity: 0; transform: translateY(6px); } }
  }
  @keyframes caliper-docs-shimmer { to { background-position: -150% 0; } }
  @keyframes onboarding-rise { from { opacity: 0; transform: translateY(6px); } }
  @keyframes caliper-mc-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
  @keyframes caliper-mc-grow { from { transform: scale(0); } }
  @keyframes caliper-mc-rise { from { transform: scaleY(0); } }
  @keyframes caliper-mc-fill-x { from { transform: scaleX(0); } }
  @keyframes caliper-mc-draw { from { stroke-dasharray: 1; stroke-dashoffset: 1; } to { stroke-dasharray: 1; stroke-dashoffset: 0; } }
  @keyframes caliper-mc-fade { from { opacity: 0; } }
  @keyframes caliper-live-ring { from { opacity: 0.55; transform: scale(1); } to { opacity: 0; transform: scale(2.8); } }
  @keyframes caliper-live-blink { to { opacity: 0.3; } }
  @keyframes caliper-block-arrive { from { opacity: 0; transform: translateY(calc(var(--motion-showcase-distance) / 2)); } }
  @keyframes caliper-live-good { from { background-color: color-mix(in srgb, var(--success) 30%, transparent); } }
  @keyframes caliper-live-bad { from { background-color: color-mix(in srgb, var(--destructive) 28%, transparent); } }
  @keyframes crm-bar-in { from { transform: scaleX(0); } }
}
